export function calculateResult(scores, preferredType, preferredWing) {
 if (!Array.isArray(scores)||scores.length!==9||scores.some(s=>!Number.isInteger(s)||s<0||s>5)) throw new Error('올바르지 않은 응답입니다.');
 const total=scores.reduce((a,b)=>a+b,0); if(!total) return null;
 const maximum=Math.max(...scores),ties=animals.filter(a=>scores[a.id-1]===maximum).map(a=>a.id);
 const type=ties.includes(preferredType)?preferredType:ties[0];
 const left=type===1?9:type-1,right=type===9?1:type+1;
 const wingCandidates=scores[left-1]===scores[right-1]?[left,right]:[scores[left-1]>scores[right-1]?left:right];
 const wing=wingCandidates.includes(preferredWing)?preferredWing:wingCandidates[0];
 const percentages=scores.map(s=>Math.floor(s/total*100));
 let remainder=100-percentages.reduce((a,b)=>a+b,0);
 scores.map((s,i)=>({i,r:s/total*100-percentages[i]})).sort((a,b)=>b.r-a.r||a.i-b.i).slice(0,remainder).forEach(({i})=>percentages[i]++);
 return {type,wing,ties,wingCandidates,percentages,scores,total};
}
